  resultsPath: string,
  outputPath: string,
): Promise<Array<Omit<PlaywrightScreenshot, "comparison">>> {
  const files = (await findPngFiles(resultsPath))
    .filter((file) => classifyPlaywrightScreenshot(file) !== undefined)
    .sort((left, right) => path.basename(left).localeCompare(path.basename(right)));
  validatePlaywrightScreenshotBudget(files.length, 0);
  const imagePath = path.join(outputPath, "images");
  await mkdir(imagePath, { recursive: true });

  const screenshots: Array<Omit<PlaywrightScreenshot, "comparison">> = [];
  let totalScreenshotBytes = 0;
  for (const [index, file] of files.entries()) {
    const info = await stat(file);
    if (!info.isFile() || info.size <= 0 || info.size > MAX_PNG_SCREENSHOT_BYTES) {
      throw new Error(`Invalid screenshot size for ${file}`);
    }
    totalScreenshotBytes += info.size;
    validatePlaywrightScreenshotBudget(files.length, totalScreenshotBytes);
    const screenshot = await readFile(file);
    validatePngScreenshot(screenshot, file);
    const captureType = classifyPlaywrightScreenshot(file);
    if (captureType === undefined) continue;
    const source = path.relative(resultsPath, file);
    const baseName = sanitizeFileName(path.basename(file));
    const fileName = `${String(index + 1).padStart(3, "0")}-${baseName}`;
    await copyFile(file, path.join(imagePath, fileName));
    screenshots.push({
      captureType,
      fileName: `images/${fileName}`,
      hash: createHash("sha256").update(screenshot).digest("hex"),
      source,
      testId: testIdFromSource(source),
      title: screenshotTitleFromFileName(baseName),
    });
  }
  return screenshots;
}

async function findPngFiles(
  directory: string,
  depth = 0,
  budget = { entries: 0 },
): Promise<string[]> {
  if (depth > MAX_ARTIFACT_DEPTH) {
    throw new Error(`Playwright artifact exceeds maximum directory depth of ${MAX_ARTIFACT_DEPTH}`);
  }
  let entries: Dirent[];
  try {
    entries = await readdir(directory, { withFileTypes: true });
  } catch (error) {
    if (isNodeError(error) && error.code === "ENOENT") return [];
    throw error;
  }
  budget.entries += entries.length;
  if (budget.entries > MAX_ARTIFACT_ENTRIES) {
    throw new Error(`Playwright artifact exceeds maximum entry count of ${MAX_ARTIFACT_ENTRIES}`);
  }

  const files = await Promise.all(
    entries.map(async (entry) => {
      const entryPath = path.join(directory, entry.name);
      if (entry.isDirectory() && entry.name === "attachments") return [];
      if (entry.isDirectory()) return findPngFiles(entryPath, depth + 1, budget);
      return entry.isFile() && entry.name.toLowerCase().endsWith(".png") ? [entryPath] : [];
    }),
  );
  return files.flat();
}

function sanitizeFileName(fileName: string): string {
  return fileName.replaceAll(/[^a-zA-Z0-9._-]/g, "-");
}

function testIdFromSource(source: string): string {
  const directory = path.dirname(source);
  return directory === "." ? "Unknown test" : directory.split(path.sep).join(" / ");
}

function getRequiredEnvironmentVariable(name: string): string {
  const value = process.env[name];
  if (!value) throw new Error(`${name} is required`);
  return value;
}

function getOptionalHttpsEnvironmentVariable(name: string): string | undefined {
  const value = process.env[name]?.trim();
  if (!value) return undefined;
  if (!URL.canParse(value) || new URL(value).protocol !== "https:") {
    throw new Error(`${name} must use HTTPS`);
  }
  return value;
}

function getRequiredNumber(name: string): number {
  const value = Number(getRequiredEnvironmentVariable(name));
  if (!Number.isFinite(value)) throw new Error(`${name} must be a number`);
  return value;
}

function getOptionalNumber(name: string): number | undefined {
  const value = process.env[name]?.trim();
  if (!value) return undefined;
  const parsed = Number(value);
  if (!Number.isInteger(parsed) || parsed <= 0)
    throw new Error(`${name} must be a positive integer`);
  return parsed;
}

async function readHistory(filePath: string): Promise<unknown> {
  try {
    return JSON.parse(await readFile(filePath, "utf8"));
  } catch (error) {
    if (isNodeError(error) && error.code === "ENOENT") return [];
    throw error;
  }
}

async function readOptionalJson(filePath: string | undefined): Promise<unknown> {
  if (!filePath) return undefined;
  try {
    const info = await stat(filePath);
    if (!info.isFile() || info.size > 1_000_000) {
      console.warn("Ignoring an invalid or oversized Playwright baseline manifest.");
      return undefined;
    }
    return JSON.parse(await readFile(filePath, "utf8"));
  } catch (error) {
    if (isNodeError(error) && error.code === "ENOENT") return undefined;
    if (error instanceof SyntaxError) {
      console.warn("Ignoring an invalid Playwright baseline manifest.");
      return null;
    }
    throw error;
  }
}

function isNodeError(error: unknown): error is NodeJS.ErrnoException {
  return error instanceof Error && "code" in error;
}

# End-to-end tests coding guide

End-to-end (E2E for short) tests are meant to test the behavior of your application, from start to finish.

While unit tests are the first choice for catching bugs and regression on individual components, it is a good idea to
complement them with test cases covering the integration between the individual components, hence the need for E2E
tests.

These tests use [Cypress](https://www.cypress.io/), which is a next generation front end testing tool built for the modern web.

If you are new to Cypress, you can read the [introduction guide](https://docs.cypress.io/guides/core-concepts/introduction-to-cypress#Cypress-Can-Be-Simple-Sometimes), as although it seems similar on the surface as other tools like Selenium or Protractor, Cypress is fundamentally different.

## Good practices

- Avoid whenever possible inter-dependencies between your E2E tests
- Run E2E tests on your continuous integration server against different browsers
- If you use an Agile methodology, cover each user story acceptance factors with an E2E test

## Page objects

E2E tests should follow the *[Page Object](https://github.com/SeleniumHQ/selenium/wiki/PageObjects)* pattern.

#### What is a page object?

A page object:

- Models the objects on a page under test:
  * *Properties* wrap page elements
  * *Methods* wrap code that interacts with the page elements
- Simplifies the test scripts
- Reduces the amount of duplicated code

If the UI changes, the fix only needs to be applied in one place.

#### How to define a page object

```typescript
// login.po.ts
export class LoginPage {
  get emailInput() {
    return cy.get('input[name=^"email"]');
  }

  get passwordInput() {
    return cy.get('input[name=^"password"]');
  }

  get loginButton() {
    return cy.get('button[(click)^="login"]');
  }

  get registerButton() {
    return cy.get('button[(click)^="register"]');
  }

  get greeting() {
    return cy.get('.greeting');
  }

  visit() {
    cy.visit('/');
  }
}
```

#### How to use a page object

```typescript
// login.e2e-spec.ts
import { LoginPage } from './login.po';

describe('Login', () => {
  let page: LoginPage;

  beforeEach(async () => {
    page = new LoginPage();
    page.visit();
  });

  it('should navigate to the register page when the register button is clicked', () => {
    page.registerButton.click();
    cy.url().should('include', '/register');
  });

  it('should allow a user to log in', async () => {
    page.emailInput.type('test@mail.com');
    page.passwordInput.type('abc123');
    page.loginButton.click();
    page.greeting.contains('Welcome, Test User');
  });
});
```

